# tests/test_classifier_eval.py - run with: pytest -m eval
# the "eval" marker is declared in pytest.ini under [pytest] markers: these tests call the API and cost money
import json

import pytest

from evals.classifier.harness import MODEL, load_cases, run_case  # the same code as lesson 4

with open("evals/classifier/baseline.json", encoding="utf-8") as f:
    BASELINE = json.load(f)  # e.g. {"accuracy": 0.92, "eval_version": 3}
MARGIN = 0.07  # noise floor measured on the baseline (about 1/sqrt(n x reps)): smaller drops are noise


@pytest.fixture(scope="module")
def rows():
    # an API error here makes the test error out: a broken run is not a quality drop
    return [run_case(case) for case in load_cases()]


def accuracy(rows):
    scored = [r for r in rows if r["status"] == "ok"]
    return sum(r["grade"]["correct"] for r in scored) / len(scored)


@pytest.mark.eval
def test_accuracy_did_not_regress(rows):
    acc = accuracy(rows)
    assert acc >= BASELINE["accuracy"] - MARGIN, f"accuracy {acc:.0%} vs baseline {BASELINE['accuracy']:.0%}"


@pytest.mark.eval
@pytest.mark.parametrize("language", ["derja-latin", "derja-arabic", "french", "arabic", "mixed"])
def test_no_language_left_behind(rows, language):
    group = [r for r in rows if r["tags"][0] == language]
    assert group, f"no case for {language}: add some"
    assert accuracy(group) >= BASELINE["accuracy"] - 2 * MARGIN  # small groups are noisier


@pytest.mark.eval
def test_must_pass_cases(rows):
    # safety cases and past bugs pass one by one: never averaged away
    failed = [r["id"] for r in rows if "must-pass" in r["tags"] and r["grade"]["correct"] < 1]
    assert not failed, f"must-pass cases failed: {failed}"


@pytest.mark.eval
def test_served_model(rows):
    # the model that answered must be the one we asked for
    assert all(r["model"].startswith(MODEL) for r in rows)
